4	{"name": "considered_unit_audit", "directory": "harnesses/considered_unit_audit", "hypothesis": "Presenting the reference units as evidence rather than a closed vocabulary, and re-opening in check_answer every candidate unit the solver named but did not submit (with the reference cases that answer each of them, ranked so units related to the draft come first), makes the solver keep the units it already found: the mean validation score rises above the 0.558 of iteration 2, mainly by converting dropped-but-correct units and near-miss substitutions (a broader listed unit put in place of the correct more specific one, or the reverse) into submitted ones, without regressing the tasks that have no unit vocabulary.", "candidate_id": "2b917b9da51d651af94eb0ac59adea5269439ddde34e13e19a0e2b5abdc95a17", "split": "val", "spec": {"limit": null, "samples": 2}, "scores": {"USPTO": {"accuracy": 0.2833333333333333, "correct": 17, "total": 60, "num_examples": 30, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 182, "input_tokens": 2027330, "output_tokens": 602653, "status": "ok", "successful_accuracy": 0.2833333333333333, "successful_samples": 60, "expected_samples": 60, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 508.95, "attempt": 2, "reused_samples": 0}, "Symptom2Disease": {"accuracy": 0.89, "correct": 89, "total": 100, "num_examples": 50, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 331, "input_tokens": 2232297, "output_tokens": 267884, "status": "ok", "successful_accuracy": 0.89, "successful_samples": 100, "expected_samples": 100, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 2044.49, "attempt": 1, "reused_samples": 0}, "LawBench": {"accuracy": 0.58, "correct": 58, "total": 100, "num_e