        self.idf = {g: math.log((self.N + 1) / (c + 1)) + 1.0 for g, c in df.items()}
        self.default_idf = math.log(self.N + 1) + 1.0
        self.norms = []
        for s in self.gs:
            self.norms.append(math.sqrt(sum(self.idf.get(g, self.default_idf) ** 2 for g in s)) or 1.0)
        self.avgdl = sum(len(s) for s in self.gs) / max(1, self.N)

    def score(self, query, i):
        qg = grams(query, self.n)
        s = self.gs[i]
        shared = qg & s
        if not shared:
            return 0.0
        idf = self.idf.get
        d = self.default_idf
        if self.mode == "cos":
            num = sum(idf(g, d) ** 2 for g in shared)
            qn = math.sqrt(sum(idf(g, d) ** 2 for g in qg)) or 1.0
            return num / (qn * self.norms[i])
        if self.mode == "idf":
            num = sum(idf(g, d) for g in shared)
            return num / (len(qg) ** 0.5 * len(s) ** 0.5)
        if self.mode == "bm25":
            k1, b = 1.5, 0.75
            num = 0.0
            for g in shared:
                num += idf(g, d) * (k1 + 1) / (1 + k1 * (1 - b + b * len(s) / self.avgdl))
            return num
        raise ValueError(self.mode)

    def ranks(self, queries, target_fn, answers):
        out = []
        for q, t in zip(queries, target_fn):
            sc = sorted(((self.score(q, i), i) for i in range(len(self.gs))), key=lambda x: -x[0])
            rank = 10 ** 6
            for r, (_, i) in enumerate(sc, 1):
                if t(answers[i]):
                    rank = r
                    break
            out.append(rank)
        return out

